import {lessons,challenges,answerMatches,outputMatches} from './content.mjs';
const $=id=>document.getElementById(id),KEY='glm-e3-training-v1';
const node=(tag,text,attrs={})=>{const el=document.createElement(tag);if(text!==null)el.textContent=text;for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);return el;};
const clean=s=>typeof s==='string'?s:'';
let state={version:1,lesson:0,view:'learn',challenge:'pace',checks:{},drafts:{}},worker=null,pending=null,runId=0,busy=false;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved)state=validateProgress(saved);}catch(_){/* Practice still works without storage. */}
function validateProgress(raw,resetTests=false){
 if(!raw||raw.version!==1||typeof raw.checks!=='object'||typeof raw.drafts!=='object')throw new Error('Choose a progress file exported by this training site.');
 const out={version:1,lesson:Math.min(5,Math.max(0,Math.trunc(Number(raw.lesson)||0))),view:['learn','lab','reference'].includes(raw.view)?raw.view:'learn',challenge:challenges.some(c=>c.id===raw.challenge)?raw.challenge:'pace',checks:{},drafts:{}};
 for(const lesson of lessons)for(const check of lesson.checks){const r=raw.checks[check.id];if(r){const answer=clean(r.answer).slice(0,300),attempts=Math.max(0,Math.min(1000,Math.trunc(Number(r.attempts)||0)));out.checks[check.id]={answer,attempts,passed:r.passed===true&&attempts>0&&answerMatches(answer,check.answers),hint:r.hint===true,model:r.model===true};}}
 for(const challenge of challenges){const d=raw.drafts[challenge.id];if(d&&typeof d==='object')out.drafts[challenge.id]={code:clean(d.code).slice(0,30000),inputs:clean(d.inputs).slice(0,3000),predictions:Array.from({length:4},(_,i)=>clean(d.predictions?.[i]).slice(0,1800)),logs:Array.from({length:4},(_,i)=>clean(d.logs?.[i]).slice(0,4000)),improvement:clean(d.improvement).slice(0,4000),explanation:clean(d.explanation).slice(0,4000),attempts:Math.max(0,Number(d.attempts)||0),hintCount:Math.max(0,Math.min(4,Math.trunc(Number(d.hintCount)||0))),model:d.model===true,results:!resetTests&&Array.isArray(d.results)&&d.results.length===4?d.results.map(r=>({output:clean(r.output).slice(0,22000),error:clean(r.error).slice(0,15000)})):[],testedCode:!resetTests&&d.testedCode===d.code?clean(d.testedCode).slice(0,30000):''};}
 return out;
}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(_){notice('Browser storage is unavailable. Export progress before leaving.');}renderProgress();}
function notice(text){$('notice').textContent=text;}
function activeChallenge(){return challenges.find(c=>c.id===state.challenge);}
function draft(){const c=activeChallenge();return state.drafts[c.id]??=( {code:c.starter,inputs:c.tests[0].inputs.join('\n'),predictions:['','','',''],logs:['','','',''],improvement:'',explanation:'',attempts:0,hintCount:0,model:false,results:[],testedCode:''} );}
function renderProgress(){
 const complete=lessons.flatMap(l=>l.checks).filter(c=>state.checks[c.id]?.passed).length;$('checkCount').textContent=complete+' of 12 quick checks';$('progress').value=complete;
 const programs=challenges.filter(c=>{const d=state.drafts[c.id];return d&&d.testedCode===d.code&&d.results?.length===4&&d.results.every(r=>!r.error&&outputMatches(r.output,c.tests[d.results.indexOf(r)].expected));}).length;
 $('labCount').textContent=programs+' of 3 programs tested';
 for(let i=0;i<lessons.length;i++){const b=$('lesson-'+i);if(b)b.classList.toggle('done',lessons[i].checks.every(c=>state.checks[c.id]?.passed));}
}
function setView(view){state.view=view;for(const key of ['learn','lab','reference']){$(key+'View').hidden=key!==view;$(key+'Tab').setAttribute('aria-pressed',String(key===view));}persist();}
function buildNavigation(){lessons.forEach((lesson,i)=>{const b=node('button',null,{id:'lesson-'+i,class:'lesson-link',type:'button'});b.append(node('span',String(i+1).padStart(2,'0'),{class:'lesson-number'}),node('span',lesson.title));b.addEventListener('click',()=>{state.lesson=i;renderLesson();setView('learn');});$('lessonNav').append(b);});challenges.forEach(c=>{const option=node('option',c.title);option.value=c.id;$('challengeSelect').append(option);});}
function renderLesson(){
 const l=lessons[state.lesson];$('lessonMeta').textContent='LESSON '+(state.lesson+1)+' OF 6 · '+l.time;$('lessonTitle').textContent=l.title;$('lessonIntro').textContent=l.intro;$('lessonCode').textContent=l.code;$('lessonPoints').replaceChildren(...l.points.map(p=>node('li',p)));$('quickChecks').replaceChildren();
 lessons.forEach((_,i)=>{const b=$('lesson-'+i);if(i===state.lesson)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});
 l.checks.forEach((check,i)=>{
  const record=state.checks[check.id]??={answer:'',attempts:0,passed:false,hint:false,model:false};
  const card=node('article',null,{class:'card'}),head=node('div',null,{class:'check-head'});head.append(node('span','QUICK CHECK '+(i+1)),node('span',record.passed?'Complete':'Try it first'));card.append(head,node('p',check.prompt),node('pre',check.code));
  const label=node('label','Your answer',{for:check.id,class:'hint'}),input=node('input',null,{id:check.id,type:'text',maxlength:'300',autocomplete:'off'});input.value=record.answer;card.append(label,input);
  const actions=node('div',null,{class:'actions'}),verify=node('button','Check answer'),hint=node('button','Hint',{class:'secondary'}),model=node('button','Show answer',{class:'quiet'}),feedback=node('p','',{class:'feedback','aria-live':'polite'});
  verify.addEventListener('click',()=>{record.answer=input.value;record.attempts++;record.passed=answerMatches(input.value,check.answers);feedback.textContent=record.passed?'Correct. '+check.why:'Try again. '+check.hint;feedback.className='feedback '+(record.passed?'good':'retry');head.lastChild.textContent=record.passed?'Complete':'Try again';persist();lessonStatus();});
  input.addEventListener('input',()=>{record.answer=input.value;record.passed=false;feedback.textContent='';head.lastChild.textContent='Check your answer';persist();lessonStatus();});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();verify.click();}});
  hint.addEventListener('click',()=>{record.hint=true;feedback.textContent=check.hint;feedback.className='feedback';persist();});
  model.addEventListener('click',()=>{if(!record.attempts){feedback.textContent='Make a prediction and click Check answer first.';return;}record.model=true;feedback.textContent='Answer: '+check.answers[0]+'. '+check.why;feedback.className='feedback';persist();});
  actions.append(verify,hint,model);card.append(actions,feedback);if(record.passed){feedback.textContent='Completed. '+check.why+(record.model?' You used the model answer.':'');feedback.className='feedback good';}$('quickChecks').append(card);
 });lessonStatus();renderProgress();
}
function lessonStatus(){const l=lessons[state.lesson],done=l.checks.every(c=>state.checks[c.id]?.passed);$('lessonComplete').textContent=done?'Both quick checks completed. Explain the idea aloud before moving on.':'';$('nextLesson').textContent=state.lesson===5?'Open debugging lab →':'Next lesson →';}
function renderLab(){
 const c=activeChallenge(),d=draft();$('challengeSelect').value=c.id;$('challengeTitle').textContent=c.title;$('challengeLevel').textContent=c.level;$('challengeTask').textContent=c.task;$('pythonCode').value=d.code;$('pythonInputs').value=d.inputs;$('modelDetails').hidden=!d.model;$('modelDetails').open=false;$('modelCode').textContent=c.solution;$('labHint').textContent=d.hintCount?c.hints[d.hintCount-1]:'';$('hintButton').textContent=d.hintCount>=4?'All hints shown':'Show next hint';$('testCases').replaceChildren();$('debugNotebook').replaceChildren();$('improvementNote').value=d.improvement;$('explanationNote').value=d.explanation;$('testSummary').textContent='';$('pythonOutput').textContent='Your program output will appear here.';
 c.tests.forEach((test,i)=>{
  const card=node('article',null,{class:'test-case'});card.append(node('h3',(i+1)+'. '+test.label),node('p','Inputs, in order: '+test.inputs.join(' → '),{class:'inputs'}));
  const label=node('label','Your predicted complete output',{for:'prediction-'+i}),area=node('textarea',null,{id:'prediction-'+i,rows:'3',maxlength:'1800'});area.value=d.predictions[i]||'';area.addEventListener('input',()=>{d.predictions[i]=area.value;persist();});
  const actual=node('pre','Not run yet',{id:'actual-'+i,'aria-label':test.label+' actual output'}),status=node('p','',{id:'result-'+i,class:'hint'});card.append(label,area,actual,status);$('testCases').append(card);
 });
 for(let i=0;i<4;i++){const details=node('details',null,{class:'log-entry'});details.append(node('summary','Repair '+(i+1)));const label=node('label','Symptom · isolated cause · original line · corrected line · retest evidence');const area=node('textarea',null,{maxlength:'4000','aria-label':'Repair '+(i+1)+' notebook'});area.value=d.logs[i]||'';area.addEventListener('input',()=>{d.logs[i]=area.value;persist();});label.append(area);details.append(label);$('debugNotebook').append(details);}
 showTestResults();persist();
}
function showTestResults(){const c=activeChallenge(),d=draft();if(d.testedCode!==d.code||!d.results?.length)return;let correct=0,predicted=0;d.results.forEach((r,i)=>{const pass=!r.error&&outputMatches(r.output,c.tests[i].expected);if(pass)correct++;if(!r.error&&outputMatches(r.output,d.predictions[i])&&outputMatches(d.predictions[i],c.tests[i].expected))predicted++;$('actual-'+i).textContent=r.error?r.output+'\n'+r.error:r.output||'(No output)';$('result-'+i).textContent=(pass?'Required behavior passes.':'Required behavior needs a repair. Expected:\n'+c.tests[i].expected)+(d.predictions[i].trim()?(outputMatches(d.predictions[i],c.tests[i].expected)?' Prediction matches.':' Review your prediction.'):'');});$('testSummary').textContent=correct+' of 4 program tests pass. '+predicted+' of 4 predictions match.'+(d.model?' Model solution used.':'');renderProgress();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=node('a',null);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function runner(code,inputs){return new Promise((resolve,reject)=>{
 if(pending){reject(new Error('A program is already running.'));return;}
 if(!worker){worker=new Worker(new URL('./python-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=event=>{const m=event.data,p=pending;if(!p||m.id!==p.id)return;if(m.status==='loading'){$('runtimeStatus').textContent='Loading Python…';return;}if(m.status==='running'){clearTimeout(p.timer);p.timer=setTimeout(()=>stopRunner('Run stopped after 8 seconds. Check the stopping condition in your loop.'),8000);$('runtimeStatus').textContent='Running…';return;}if(m.status==='done'||m.status==='failed'){clearTimeout(p.timer);pending=null;$('runtimeStatus').textContent=m.status==='done'?'Python ready':'Loading failed';m.status==='done'?p.resolve(m):p.reject(new Error(m.error));}};worker.onerror=()=>stopRunner('Python could not start. Check your connection, or download your code and use GLM Python Lab.');}
 const id=++runId;pending={id,resolve,reject,timer:setTimeout(()=>stopRunner('Python did not load within 60 seconds. Check your connection or use GLM Python Lab.'),60000)};worker.postMessage({id,code,inputs});
 });}
function stopRunner(reason='Stopped. You can edit and run again.'){if(worker)worker.terminate();worker=null;if(pending){clearTimeout(pending.timer);const p=pending;pending=null;p.reject(new Error(reason));}$('runtimeStatus').textContent='Stopped';}
function setBusy(value){busy=value;for(const id of ['runCode','checkTests','challengeSelect','resetCode','loadModel','modelButton','hintButton','tryExample','importProgress'])$(id).disabled=value;$('pythonCode').readOnly=value;$('pythonInputs').readOnly=value;$('stopCode').disabled=!value;}
async function runCurrent(){if(busy)return;const d=draft();d.attempts++;persist();setBusy(true);$('pythonOutput').textContent='Starting Python…';try{const inputs=d.inputs.trim()?d.inputs.replace(/\r/g,'').trimEnd().split('\n'):[];const r=await runner(d.code,inputs);$('pythonOutput').textContent=(r.output||'')+(r.error?'\n'+r.error:'')||'(No output)';}catch(error){$('pythonOutput').textContent=error.message;}finally{setBusy(false);}}
async function runTests(){if(busy)return;const d=draft(),c=activeChallenge();if(d.predictions.some(p=>!p.trim())){notice('Write a prediction for all four cases before checking the program.');$('prediction-'+d.predictions.findIndex(p=>!p.trim())).focus();return;}notice('');d.attempts++;d.results=[];d.testedCode='';persist();setBusy(true);try{for(let i=0;i<4;i++){$('testSummary').textContent='Running test '+(i+1)+' of 4…';const r=await runner(d.code,c.tests[i].inputs);d.results.push({output:r.output,error:r.error});$('actual-'+i).textContent=r.error?r.output+'\n'+r.error:r.output;}d.testedCode=d.code;showTestResults();persist();}catch(error){$('testSummary').textContent=error.message;d.results=[];persist();}finally{setBusy(false);}}
buildNavigation();renderLesson();renderLab();setView(state.view);
$('learnTab').addEventListener('click',()=>setView('learn'));$('labTab').addEventListener('click',()=>setView('lab'));$('referenceTab').addEventListener('click',()=>setView('reference'));
$('nextLesson').addEventListener('click',()=>{if(state.lesson===5){setView('lab');}else{state.lesson++;renderLesson();persist();}});
$('tryExample').addEventListener('click',()=>{const d=draft();if(d.code!==activeChallenge().starter){notice('Your existing lab code is preserved. Download it or restore the starter before loading a lesson example.');setView('lab');return;}const examples=[{prefix:'',inputs:'Sam\n4\n2.5\n007'},{prefix:'price = 8.0\nquantity = 3\na, b, c = 3, 6, 9\ncorrect = 7\nquestions = 10\nside = 4\n',inputs:''},{prefix:'score = 12\ntarget = 12\n',inputs:''},{prefix:'',inputs:''},{prefix:'',inputs:'2.5\n4\n1.5'},{prefix:'points = 18\ntarget = 14\n',inputs:''}];const ex=examples[state.lesson];d.code=ex.prefix+lessons[state.lesson].code;if(state.lesson===0)d.code+='\nprint(name, pages, minutes, room_code, bonus)';if(state.lesson===1)d.code+='\nprint(total, average, percentage, discount, square_area)';d.inputs=ex.inputs;d.results=[];d.testedCode='';renderLab();setView('lab');notice('Lesson example loaded with sample inputs. Restore the challenge starter when you want to test its requirements.');});
$('challengeSelect').addEventListener('change',()=>{state.challenge=$('challengeSelect').value;renderLab();notice('');});
$('pythonCode').addEventListener('input',()=>{const d=draft();d.code=$('pythonCode').value;d.testedCode='';d.results=[];$('testSummary').textContent='Code changed. Rerun your four tests.';persist();});
$('pythonCode').addEventListener('keydown',event=>{if(event.key==='Tab'){event.preventDefault();const el=event.target;el.setRangeText('    ',el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();runCurrent();}});
$('pythonInputs').addEventListener('input',()=>{draft().inputs=$('pythonInputs').value;persist();});
$('hintButton').addEventListener('click',()=>{const d=draft(),c=activeChallenge();d.hintCount=Math.min(4,d.hintCount+1);$('labHint').textContent=c.hints[d.hintCount-1];$('hintButton').textContent=d.hintCount===4?'All hints shown':'Show next hint';persist();});
$('modelButton').addEventListener('click',()=>{const d=draft();if(!d.attempts){$('labHint').textContent='Try running your code or checking the tests first. Then compare with the model.';return;}d.model=true;$('modelDetails').hidden=false;$('modelDetails').open=true;persist();});
$('loadModel').addEventListener('click',()=>{const d=draft();d.code=activeChallenge().solution;d.testedCode='';d.results=[];renderLab();notice('Model loaded. Run it, explain each repair and then try a fresh program.');});
$('resetCode').addEventListener('click',()=>$('confirmReset').showModal());$('cancelReset').addEventListener('click',()=>$('confirmReset').close());$('doReset').addEventListener('click',()=>{const d=draft();d.code=activeChallenge().starter;d.results=[];d.testedCode='';$('confirmReset').close();renderLab();});
$('runCode').addEventListener('click',runCurrent);$('checkTests').addEventListener('click',runTests);$('stopCode').addEventListener('click',()=>stopRunner());$('downloadCode').addEventListener('click',()=>download('practice_'+state.challenge+'.py',draft().code,'text/x-python'));
$('improvementNote').addEventListener('input',()=>{draft().improvement=$('improvementNote').value;persist();});$('explanationNote').addEventListener('input',()=>{draft().explanation=$('explanationNote').value;persist();});
$('exportProgress').addEventListener('click',()=>download('GLM_Python_Training_Progress.json',JSON.stringify(state,null,2)));
$('importProgress').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>600000)throw new Error('Choose a progress file smaller than 600 KB.');const incoming=validateProgress(JSON.parse(await file.text()),true);state=incoming;renderLesson();renderLab();setView(state.view);persist();notice('Progress imported. Rerun program tests to refresh their results.');}catch(error){notice(error.message||'The progress file could not be read.');}event.target.value='';});
